import 'dart:convert';

class RequestsModel {
  int? requestFromLawyerId;
  int? propertyForSaleId;
  String? statusRequest;
  String? acceptAdmin;
  String? byWhom;
  String? userName;
  String? createdAt;
  String? agreedNegotiationStatus;
  String? propertyInfo;

  RequestsModel({
    this.requestFromLawyerId,
    this.propertyForSaleId,
    this.statusRequest,
    this.acceptAdmin,
    this.byWhom,
    this.userName,
    this.createdAt,
    this.agreedNegotiationStatus,
    this.propertyInfo,
  });

  factory RequestsModel.(
    Map<String, dynamic> data,
  ) {
    return RequestsModel(
      requestFromLawyerId: data['request_from_lawyer_id'] as int?,
      propertyForSaleId: data['property_for_sale_id'] as int?,
      statusRequest: data['status_request'] as String?,
      acceptAdmin: data['accept_admin'] as String?,
      byWhom: data['by_whom'] as String?,
      userName: data['user_name'] as String?,
      createdAt: data['created_at'] as String?,
      agreedNegotiationStatus: data['agreed_negotiation_status'] as String?,
      propertyInfo: data['property_info'] as String?,
    );
  }

  Map<String, dynamic>
  () {
    return {
      'request_from_lawyer_id': requestFromLawyerId,
      'property_for_sale_id': propertyForSaleId,
      'status_request': statusRequest,
      'accept_admin': acceptAdmin,
      'by_whom': byWhom,
      'user_name': userName,
      'created_at': createdAt,
      'agreed_negotiation_status': agreedNegotiationStatus,
      'property_info': propertyInfo,
    };
  }

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [RequestsModel].
  factory RequestsModel.fromJson(String data) {
    return RequestsModel.(
      json.decode(data) as Map<String, dynamic>,
    );
  }

  /// `dart:convert`
  ///
  /// Converts [RequestsModel] to a JSON string.
  String toJson() => json.encode(
    (),
  );
}
